package pl.zagranietyper.service;import pl.zagranietyper.fixture.ApiFootballClient;import pl.zagranietyper.model.FootballFixturePlayerStatisticsSnapshot;import pl.zagranietyper.repository.FootballFixturePlayerStatisticsRepository;
public final class FootballFixturePlayerStatisticsIngestionService {private final ApiFootballClient client;private final FootballFixturePlayerStatisticsRepository repository;private final FootballFixturePlayerStatisticsNormalizer normalizer;public FootballFixturePlayerStatisticsIngestionService(ApiFootballClient c,FootballFixturePlayerStatisticsRepository r,FootballFixturePlayerStatisticsNormalizer n){client=c;repository=r;normalizer=n;}public FootballFixturePlayerStatisticsSnapshot inspect(long id){return normalizer.normalize(client.fetchFixturePlayers(id));}public FootballFixturePlayerStatisticsSnapshot ingest(long id){var s=inspect(id);repository.store(s);return s;}}
